17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (owner.getRegistrationDate() == null) {
111	            owner.setRegistrationDate(LocalDate.now());
112	        }
113	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
114	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    /**
123	     * Generates the customer code for a newly created owner. The code is formatted as
124	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
125	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
126	     * Cities are matched ignoring letter case.
127	     */
128	    private String generateCustomerCode(String city) {
129	        long ownersInCity = this.clinicService.findAllOwners().stream()
130	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
131	            .count();
132	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
133	    }
134	
135	    /**
136	     * Determines whether an owner already exists that uses the same telephone number
137	     * as the given one. Telephone numbers must be unique across all owners. The
138	     * comparison ignores letter case and any surrounding or repeated whitespace.
139	     */
140	    private boolean isDuplicateOwner(Owner owner) {
141	        String telephone = normalize(owner.getTelephone());
142	        return this.clinicService.findAllOwners().stream()
143	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
144	    }
145	
146	    /**
147	     * Determines whether another owner already uses the same email address as the given one.
148	     * Email addresses, when supplied, must be unique across all owners. An owner without an
149	     * email address is never considered a duplicate. The comparison ignores letter case and
150	     * any surrounding or repeated whitespace.
151	     */
152	    private boolean isDuplicateEmail(Owner owner) {
153	        String email = normalize(owner.getEmail());
154	        if (email == null || email.isEmpty()) {
155	            return false;
156	        }
157	        return this.clinicService.findAllOwners().stream()
158	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
159	    }
160	
161	    /**
162	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
163	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
164	     * and "John Smith" normalize to the same key and so count as the same person.
165	     */
166	    private static String normalize(String value) {
167	        if (value == null) {
168	            return null;
169	        }
170	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
185	        this.clinicService.saveOwner(currentOwner);
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Transactional
191	    @Override
192	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        this.clinicService.deleteOwner(owner);
198	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        HttpHeaders headers = new HttpHeaders();
209	        Pet pet = petMapper.toPet(petFieldsDto);
210	        owner.setId(ownerId);
211	        pet.setOwner(owner);
212	        pet.getType().setName(null);
213	        this.clinicService.savePet(pet);
214	        PetDto petDto = petMapper.toPetDto(pet);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
216	            .buildAndExpand(pet.getId()).toUri());
217	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner != null) {
225	            Pet currentPet = this.clinicService.findPetById(petId);
226	            if (currentPet != null) {
227	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
228	                currentPet.setName(petFieldsDto.getName());
229	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
230	                this.clinicService.savePet(currentPet);
231	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
240	        HttpHeaders headers = new HttpHeaders();
241	        Visit visit = visitMapper.toVisit(visitFieldsDto);
242	        Pet pet = new Pet();
243	        pet.setId(petId);
244	        visit.setPet(pet);
245	        this.clinicService.saveVisit(visit);
246	        VisitDto visitDto = visitMapper.toVisitDto(visit);
247	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
248	            .buildAndExpand(visit.getId()).toUri());
249	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
250	    }
251	
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner != null) {
258	            Pet pet = owner.getPet(petId);
259	            if (pet != null) {
260	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
261	            }
262	        }
263	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	    }
265	}
